package com.codiebutterfly.schoolrun;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.time.*;
import java.sql.Timestamp;
import static com.codiebutterfly.schoolrun.Store.*;
@RestController @RequestMapping("/api") public class Journeys {
 final Store s;final RoutePlanner planner;Journeys(Store s,RoutePlanner planner){this.s=s;this.planner=planner;}
 @SuppressWarnings("unchecked") List<Map<String,Object>> legs(Object raw){
  if(!(raw instanceof List<?> list)||list.size()>8)throw error(400,"Provide up to eight transport legs");
  for(Object item:list){if(!(item instanceof Map))throw error(400,"Invalid transport leg");var l=(Map<String,Object>)item;for(String k:List.of("pickup","dropoff"))text(l,k,300);for(String k:List.of("pickupLat","dropoffLat"))coordinate(l,k,90);for(String k:List.of("pickupLng","dropoffLng"))coordinate(l,k,180);
   if(l.get("schoolFinishTime")!=null){try{var finish=LocalTime.parse(text(l,"schoolFinishTime",5));}catch(java.time.format.DateTimeParseException e){throw error(400,"Use HH:mm finish time");}}
   try{if(!LocalTime.parse(text(l,"pickupTime",5)).isBefore(LocalTime.parse(text(l,"arrivalBy",5))))throw error(400,"Arrival deadline must follow pickup time");}catch(java.time.format.DateTimeParseException e){throw error(400,"Use HH:mm times");}}
  return (List<Map<String,Object>>)raw;
 }
 @PutMapping("/children/{id}/schedule") @Transactional Object schedule(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id,@RequestBody Map<String,Object>b){var u=s.user(a);s.role(u,"PARENT");var c=s.child(id,u);s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",c.get("driver_id"));LocalDate start=LocalDate.parse(text(b,"termStart",10)),end=LocalDate.parse(text(b,"termEnd",10));if(end.isBefore(start)||end.isAfter(start.plusYears(1)))throw error(400,"Choose a valid term of at most one year");if(!(b.get("week") instanceof Map<?,?>week))throw error(400,"Provide weekly timetable");for(var key:week.keySet()){if(!key.toString().matches("[1-7]"))throw error(400,"Weekdays must be 1–7");legs(week.get(key));}
  s.db.update("DELETE FROM sr_schedule WHERE child_id=?",id);s.db.update("INSERT INTO sr_schedule VALUES(?,?,?,?)",id,start,end,s.encode(week));s.notifyUser(c.get("driver_id"),"Timetable updated","A parent updated a term timetable.",id);return Map.of("saved",true);
 }
 @GetMapping("/children/{id}/schedule") Object schedule(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id){s.child(id,s.user(a));var rows=s.db.queryForList("SELECT * FROM sr_schedule WHERE child_id=?",id);if(rows.isEmpty())return Map.of();var row=rows.get(0);row.put("week",s.decode(row.get("week")));return row;}
 @PutMapping("/children/{id}/days/{day}") @Transactional Object override(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id,@PathVariable LocalDate day,@RequestBody Map<String,Object>b){var u=s.user(a);s.role(u,"PARENT");var c=s.child(id,u);s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",c.get("driver_id"));if(day.isBefore(LocalDate.now(ZONE)))throw error(400,"Past journeys cannot be changed");if(s.db.queryForObject("SELECT count(*) FROM sr_trip WHERE child_id=? AND journey_date=? AND state='PICKED_UP'",Integer.class,id,day)>0)throw error(409,"Your child is onboard. Contact the driver before changing this journey.");boolean absent=Boolean.TRUE.equals(b.get("absent"));var ls=absent?List.of():legs(b.get("legs"));s.db.update("DELETE FROM sr_override WHERE child_id=? AND journey_date=?",id,day);s.db.update("INSERT INTO sr_override VALUES(?,?,?,?)",id,day,absent,s.encode(ls));s.notifyUser(c.get("driver_id"),"Day schedule changed","Refresh your route: a parent changed a specific day's transport.",id);return Map.of("saved",true);}
 @DeleteMapping("/children/{id}/days/{day}") @Transactional void restore(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id,@PathVariable LocalDate day){var u=s.user(a);s.role(u,"PARENT");var c=s.child(id,u);s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",c.get("driver_id"));if(day.isBefore(LocalDate.now(ZONE)))throw error(400,"Past journeys cannot be changed");s.db.update("DELETE FROM sr_override WHERE child_id=? AND journey_date=?",id,day);}
 List<Map<String,Object>> effective(String child,LocalDate day){var over=s.db.queryForList("SELECT * FROM sr_override WHERE child_id=? AND journey_date=?",child,day);if(!over.isEmpty())return Boolean.TRUE.equals(over.get(0).get("absent"))?List.of():s.decode(over.get(0).get("legs"));var base=s.db.queryForList("SELECT * FROM sr_schedule WHERE child_id=? AND term_start<=? AND term_end>=?",child,day,day);if(base.isEmpty())return List.of();Map<String,Object>week=s.decode(base.get(0).get("week"));Object raw=week.get(String.valueOf(day.getDayOfWeek().getValue()));return raw==null?List.of():legs(raw);}
 @GetMapping("/children/{id}/week") Object week(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id,@RequestParam LocalDate start){s.child(id,s.user(a));var days=new ArrayList<Map<String,Object>>();for(int i=0;i<7;i++){var day=start.plusDays(i);var overrides=s.db.queryForList("SELECT absent FROM sr_override WHERE child_id=? AND journey_date=?",id,day);boolean changed=!overrides.isEmpty();boolean cancelled=changed&&Boolean.TRUE.equals(overrides.get(0).get("absent"));days.add(Map.of("date",day.toString(),"legs",withReturns(effective(id,day)),"changed",changed,"cancelled",cancelled));}return days;}
 static List<Map<String,Object>> withReturns(List<Map<String,Object>> legs){
  var all=new ArrayList<Map<String,Object>>(legs);
  for(var leg:legs){
   if(leg.get("schoolFinishTime")==null)continue;
   var finish=LocalTime.parse(leg.get("schoolFinishTime").toString());
   if(!finish.isAfter(LocalTime.parse(leg.get("arrivalBy").toString())))continue;
   boolean exists=legs.stream().anyMatch(other->Objects.equals(other.get("pickupLat"),leg.get("dropoffLat"))&&Objects.equals(other.get("pickupLng"),leg.get("dropoffLng"))&&!LocalTime.parse(other.get("pickupTime").toString()).isBefore(finish));
   if(exists)continue;
   var back=new LinkedHashMap<String,Object>();
   for(String suffix:List.of("","Lat","Lng")){back.put("pickup"+suffix,leg.get("dropoff"+suffix));back.put("dropoff"+suffix,leg.get("pickup"+suffix));}
   back.put("pickupTime",finish.toString());back.put("arrivalBy",finish.toString());back.put("schoolFinishTime",finish.toString());back.put("automaticReturn",true);back.put("noArrivalDeadline",true);all.add(back);
  }
  return all;
 }
 @GetMapping("/route") @Transactional Object route(@RequestHeader(value="Authorization",required=false)String a,@RequestParam LocalDate day){var u=s.user(a);s.role(u,"DRIVER");return routeFor(u,day);}
 Map<String,Object> routeFor(Map<String,Object>u,LocalDate day){
  s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",u.get("id"));
  var children=s.db.queryForList("SELECT c.* FROM sr_child c JOIN sr_link l ON l.id=c.link_id WHERE l.driver_id=?",u.get("id"));Set<String> desired=new HashSet<>();
  for(var c:children){if("CHILD".equals(s.billingUnit))s.accrue(c.get("link_id"));if(!s.serviceEnabled(c.get("link_id")))continue;List<Map<String,Object>>ls=withReturns(effective(c.get("id").toString(),day));for(int i=0;i<ls.size();i++){String tid=c.get("id")+":"+day+":"+i;desired.add(tid);var old=s.db.queryForList("SELECT * FROM sr_trip WHERE id=?",tid);boolean paid=s.paid(c.get("link_id"),YearMonth.from(day).toString());if(old.isEmpty()){if(paid)s.db.update("INSERT INTO sr_trip(id,child_id,journey_date,leg_index,state,details) VALUES(?,?,?,?,?,?)",tid,c.get("id"),day,i,"PENDING",s.encode(ls.get(i)));}else if(Set.of("PENDING","SKIPPED").contains(old.get(0).get("state"))){s.db.update("UPDATE sr_trip SET state=?,details=? WHERE id=?",paid?"PENDING":"SKIPPED",s.encode(ls.get(i)),tid);}}}
  var rows=s.db.queryForList("SELECT t.*,c.details child_details,l.parent_id,l.link_id FROM sr_trip t JOIN sr_child c ON c.id=t.child_id JOIN (SELECT id link_id,parent_id,driver_id FROM sr_link) l ON l.link_id=c.link_id WHERE l.driver_id=? AND t.journey_date=?",u.get("id"),day);
  List<Map<String,Object>>stops=new ArrayList<>();int onboard=0;Map<String,Object>profile=s.decode(u.get("profile"));int capacity=((Number)profile.get("capacity")).intValue();
  for(var t:rows){String state=t.get("state").toString();if(state.equals("PENDING")&&!desired.contains(t.get("id"))){s.db.update("UPDATE sr_trip SET state='SKIPPED' WHERE id=?",t.get("id"));state="SKIPPED";}if(state.equals("PICKED_UP"))onboard++;if(state.equals("PENDING")||state.equals("PICKED_UP")){Map<String,Object>l=s.decode(t.get("details"));Map<String,Object>c=s.decode(t.get("child_details"));Map<String,Object>stop=new LinkedHashMap<>();stop.put("id",t.get("id"));stop.put("childId",t.get("child_id"));stop.put("name",c.get("name"));stop.put("state",state);stop.put("leg",l);stops.add(stop);}}
  // Conservative fallback: finish onboard drop-offs first, then schedule each pickup/drop-off leg together.
  // No road-time or optimality claim: production routing provider is required for traffic-aware optimisation.
  stops.sort(Comparator.<Map<String,Object>,Integer>comparing(x->x.get("state").equals("PICKED_UP")?0:1).thenComparing(x->((Map<?,?>)x.get("leg")).get("pickupTime").toString()));
  var positions=s.db.queryForList("SELECT latitude,longitude FROM sr_position WHERE driver_id=? AND captured_at>?",u.get("id"),Timestamp.from(Instant.now().minusSeconds(120)));double[] origin=positions.isEmpty()?null:new double[]{((Number)positions.get(0).get("latitude")).doubleValue(),((Number)positions.get(0).get("longitude")).doubleValue()};return Map.of("day",day,"stops",stops,"plan",planner.plan(stops,capacity,origin,day),"onboard",onboard,"capacity",capacity,"routingMode","ESTIMATED_DISTANCE","notice","Suggested order uses straight-line distance, time windows and capacity. Times are estimates; road traffic routing is not configured.");
 }
 @PostMapping("/trips/{id}/{action}") @Transactional Object action(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id,@PathVariable String action){var u=s.user(a);s.role(u,"DRIVER");s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",u.get("id"));var t=s.one("SELECT * FROM sr_trip WHERE id=?",id);var c=s.child(t.get("child_id").toString(),u);LocalDate day=LocalDate.parse(t.get("journey_date").toString());if(!day.equals(LocalDate.now(ZONE)))throw error(409,"Only today's journeys can be updated");String state=t.get("state").toString();if(action.equals("gate")){if(!Set.of("PENDING","PICKED_UP").contains(state))throw error(409,"Journey is not active");s.notifyUser(c.get("parent_id"),"Driver at the gate","Your driver has sent a gate alert.",c.get("id"));return Map.of("sent",true);}
  if(action.equals("pickup")){if(state.equals("PICKED_UP"))return Map.of("state",state);routeFor(u,day);t=s.one("SELECT * FROM sr_trip WHERE id=?",id);if(!t.get("state").equals("PENDING"))throw error(409,"Pickup is no longer scheduled");if(!s.paid(c.get("link_id"),YearMonth.from(day).toString()))throw error(402,"Customer subscription is required");Map<String,Object>p=s.decode(u.get("profile"));int count=s.db.queryForObject("SELECT count(*) FROM sr_trip t JOIN sr_child c ON c.id=t.child_id JOIN sr_link l ON l.id=c.link_id WHERE l.driver_id=? AND t.state='PICKED_UP'",Integer.class,u.get("id"));if(count>=((Number)p.get("capacity")).intValue())throw error(409,"Vehicle capacity reached");if(s.db.queryForObject("SELECT count(*) FROM sr_trip WHERE child_id=? AND state='PICKED_UP'",Integer.class,c.get("id"))>0)throw error(409,"Child is already onboard");if(s.db.queryForObject("SELECT count(*) FROM sr_trip WHERE child_id=? AND journey_date=? AND leg_index<? AND state NOT IN ('DROPPED_OFF','SKIPPED')",Integer.class,c.get("id"),day,t.get("leg_index"))>0)throw error(409,"Complete the earlier journey first");state="PICKED_UP";
  }else if(action.equals("dropoff")){if(state.equals("DROPPED_OFF"))return Map.of("state",state);if(!state.equals("PICKED_UP"))throw error(409,"Confirm pickup first");state="DROPPED_OFF";}else throw error(400,"Unknown journey action");
  s.db.update("UPDATE sr_trip SET state=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",state,id);Map<String,Object> childDetails=s.decode(c.get("details"));s.db.update("INSERT INTO sr_rating_event(trip_id,action,parent_id,driver_id,child_name) SELECT ?,?,?,?,? WHERE NOT EXISTS(SELECT 1 FROM sr_rating_event WHERE trip_id=? AND action=?)",id,action,c.get("parent_id"),u.get("id"),childDetails.get("name"),id,action);s.notifyUser(c.get("parent_id"),state.equals("PICKED_UP")?"Pickup confirmed":"Drop-off confirmed",state.equals("PICKED_UP")?"Your child is onboard. Open tracking to see the latest shared driver location.":"Your driver confirmed drop-off. Live tracking has ended.",c.get("id"));return Map.of("state",state);
 }
 @PostMapping("/position") @Transactional void position(@RequestHeader(value="Authorization",required=false)String a,@RequestBody Map<String,Object>b){var u=s.user(a);s.role(u,"DRIVER");s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",u.get("id"));if(s.db.queryForObject("SELECT count(*) FROM sr_trip t JOIN sr_child c ON c.id=t.child_id JOIN sr_link l ON l.id=c.link_id WHERE l.driver_id=? AND t.state='PICKED_UP'",Integer.class,u.get("id"))==0)throw error(409,"No child is currently onboard");double lat=coordinate(b,"latitude",90),lng=coordinate(b,"longitude",180);s.db.update("DELETE FROM sr_position WHERE driver_id=?",u.get("id"));s.db.update("INSERT INTO sr_position VALUES(?,?,?,?)",u.get("id"),lat,lng,Timestamp.from(Instant.now()));}
 @GetMapping("/children/{id}/tracking") Object tracking(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id){var u=s.user(a);s.role(u,"PARENT");var c=s.child(id,u);boolean onboard=s.db.queryForObject("SELECT count(*) FROM sr_trip WHERE child_id=? AND state='PICKED_UP'",Integer.class,id)>0;if(!onboard)return Map.of("active",false);var rows=s.db.queryForList("SELECT latitude,longitude,captured_at FROM sr_position WHERE driver_id=?",c.get("driver_id"));if(rows.isEmpty())return Map.of("active",true,"available",false);var r=rows.get(0);r.put("active",true);r.put("available",true);Object raw=r.get("captured_at");Instant captured=raw instanceof OffsetDateTime od?od.toInstant():((Timestamp)raw).toInstant();r.put("stale",captured.isBefore(Instant.now().minusSeconds(60)));return r;}
}
